import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  it('throws at registration time for an uncompilable schema and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('passes valid input through to the executor', async () => {
    const registry = new ToolRegistry();
    const seen: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        seen.push(input);
        return `weather in ${String(input.location)}`;
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin'});

    expect({response, seen}).toEqual({
      response: {result: 'weather in Berlin'},
      seen: [{location: 'Berlin'}],
    });
  });

  it('returns a validation ToolResponse before invoking the executor without echoing or logging offending values', async () => {
    const logged: string[] = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>): void => {
      logged.push(JSON.stringify({category, message, fields}));
    };
    setLogger({debug: record, info: record, warn: record, error: record});

    try {
      const registry = new ToolRegistry();
      let invoked = false;
      registry.register(
        {
          name: 'get_weather',
          description: 'Get weather',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
              units: {type: 'string', enum: ['celsius', 'fahrenheit']},
            },
            required: ['location'],
          },
        },
        async () => {
          invoked = true;
          return 'ok';
        }
      );

      const secret = 'SENTINEL-SECRET-TOKEN-99';
      const response = await registry.execute('get_weather', {units: secret});
      const leakedInLogs = logged.some(line => line.includes(secret));

      expect({
        invoked,
        mentionsLocationAndRequired: response.result.includes('location') && /required/i.test(response.result),
        mentionsUnits: response.result.includes('units'),
        echoesSecret: response.result.includes(secret),
        leakedInLogs,
      }).toEqual({
        invoked: false,
        mentionsLocationAndRequired: true,
        mentionsUnits: true,
        echoesSecret: false,
        leakedInLogs: false,
      });
    } finally {
      setLogger(undefined);
    }
  });
});

