import AjvModule, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const Ajv = AjvModule as unknown as typeof AjvModule.default;
const ajv = new Ajv({allErrors: true, strict: false, verbose: false});
const validatorCache = new WeakMap<object, ValidateFunction>();

function compileSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
  const cached = validatorCache.get(schema);
  if (cached) return cached;

  try {
    const validator = ajv.compile(schema);
    validatorCache.set(schema, validator);
    return validator;
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${name}": ${detail}`);
  }
}

function formatErrorPath(err: ErrorObject): string {
  const basePath = err.instancePath ? err.instancePath.slice(1).replace(/\//g, '.') : '';
  if (err.keyword === 'required' && typeof err.params.missingProperty === 'string') {
    return basePath ? `${basePath}.${err.params.missingProperty}` : err.params.missingProperty;
  }
  return basePath || 'input';
}

function formatSchemaErrors(name: string, errors: ErrorObject[] | null | undefined): string {
  const details = (errors ?? []).map(err => `${formatErrorPath(err)} ${err.message ?? 'is invalid'}`);
  return JSON.stringify({
    error: `Invalid input for tool "${name}": ${details.join('; ')}`,
  });
}

